OUTPUT_ROWS = [
    *ORCA_5_0_OUTPUT_ROWS,
    *ORCA_6_0_OUTPUT_ROWS,
]


FIXTURE_INPUTS = {row.values[1]: row.values[2] for row in INPUT_ROWS}


def _fixture_path(relative_output):
    source_root = os.environ.get("CCLIB_SOURCE_ROOT")
    if source_root is None:
        pytest.skip("CCLIB_SOURCE_ROOT is not set")
    fixture = Path(source_root) / "data" / relative_output
    if not fixture.is_file():
        pytest.skip(f"cclib fixture is absent: {fixture}")
    return fixture


@pytest.mark.parametrize("version,relative_output,input_model,expected_input", INPUT_ROWS)
def test_generated_inputs(version, relative_output, input_model, expected_input):
    assert cclib_orca.build_input(input_model, TASK_CONFIG, "/resolved/program").input_text == expected_input


@pytest.mark.parametrize("version,relative_output,expected_output", OUTPUT_ROWS)
def test_parsed_outputs(version, relative_output, expected_output):
    output_text = _fixture_path(relative_output).read_text(encoding="utf-8", errors="replace")
    input_model = FIXTURE_INPUTS[relative_output]
    definition = cclib_orca.ORCA_DEFINITION
    result = _parse_and_convert(
        definition,
        ExecutionResult(
            process_success=True,
            executable="/fixture/program",
            input_filename=definition.input_filename,
            output_filename=definition.output_filename,
            input_text=cclib_orca.build_input(input_model, TASK_CONFIG, "/fixture/program").input_text,
            output_text=output_text,
            stdout=output_text if definition.selector == "cclib-orca" else "",
            stderr="",
        ),
        input_model,
    )
    assert json.dumps(result.dict(exclude={"extras"}), sort_keys=True, default=_json_default) == expected_output


@pytest.mark.cclib_orca
def test_live_hf_single_point():
    if not qcng.get_program("cclib-orca", check=False).found():
        pytest.skip("cclib-orca is unavailable")

    result = qcng.compute(
        AtomicInput(
            molecule={"symbols": ["He"], "geometry": [0.0, 0.0, 0.0]},
            specification={"driver": "energy", "model": {"method": "hf", "basis": "sto-3g"}},
        ),
        "cclib-orca",
        raise_error=True,
        return_version=1,
        task_config={"ncores": 1, "memory": 1.0},
    )

    assert result.success is True
    assert isinstance(result.return_result, float)
